"""Generate a dependency-free static website. Run: python3 build.py."""
from pathlib import Path
import json, html
ROOT = Path(__file__).parent
DIST = ROOT / 'dist'
CONFIG = json.loads((ROOT / 'site-config.json').read_text())
ORIGIN = CONFIG['origin'].rstrip('/')
EMAIL = CONFIG['email']
FORM = CONFIG['formspree']
esc = html.escape
PAGES = []

def header():
    return '''<a class="skip" href="#main">Skip to content</a><div class="wrap"><header class="header"><a class="brand" href="/" aria-label="Benjamin Young home">Benjamin Young<span>.</span></a><nav class="nav" aria-label="Main navigation"><a href="/#how-i-help">How I help</a><a href="/#my-story">My story</a><a class="nav-cta" href="/#contact">Let’s have a chat <span aria-hidden="true">↗</span></a></nav></header></div>'''

def footer():
    return '''<div class="wrap"><footer class="footer"><span>© 2026 Benjamin Young · Melbourne, Australia</span><div class="footer-links"><a href="/guides/">Practical AI guides</a><a href="/privacy/">Privacy</a><a href="mailto:''' + EMAIL + '''">Email Ben <span aria-hidden="true">↗</span></a></div></footer></div>'''

def contact():
    return f'''<section class="contact-section" id="contact" aria-labelledby="contact-title"><div><div class="eyebrow"><span class="dot"></span> Start with a conversation</div><h2 id="contact-title">You know your business.<br><em>Let’s make it work better.</em></h2><p>You don’t need a brief or a big idea. Tell me what’s frustrating you, what takes too long, or what you wish your software could do.</p><a class="email" href="mailto:{EMAIL}">{EMAIL}</a><div class="coffee"><svg aria-hidden="true" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M5 12h18v9a7 7 0 0 1-7 7h-4a7 7 0 0 1-7-7zM23 13h2a4 4 0 0 1 0 8h-2M10 8V3m5 5V1m5 7V3M3 31h24"/></svg><span>Based in Melbourne. Happy to meet for a coffee.</span></div></div><form id="contact-form" action="{FORM}" method="POST"><input type="hidden" name="_subject" value="New AI consulting enquiry — BenjaminYoung.com.au"><div class="hp" aria-hidden="true"><label for="website">Leave this field empty</label><input id="website" name="_gotcha" tabindex="-1" autocomplete="off"></div><div class="form-grid"><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" placeholder="Alex Smith" required maxlength="120"></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="alex@yourbusiness.com.au" required maxlength="254"></div></div><div class="field"><label for="business">Business name <span>(optional)</span></label><input id="business" name="business" autocomplete="organization" placeholder="Your business" maxlength="180"></div><div class="field"><label for="message">What would you like to make easier?</label><textarea id="message" name="message" placeholder="We spend too much time on…" required minlength="10" maxlength="5000"></textarea></div><button class="button" type="submit">Let’s have a chat <span class="arrow" aria-hidden="true">↗</span></button><p class="form-note">I’ll use your details to respond to your enquiry. <a href="/privacy/">Privacy details</a>.</p><p class="form-status" id="form-status" role="status" aria-live="polite" tabindex="-1"></p></form></section>'''

def page(path, title, description, content, schema=None, noindex=False):
    url = ORIGIN + path
    base = {'@context':'https://schema.org', '@type':'WebPage', 'name':title, 'url':url, 'description':description, 'inLanguage':'en-AU', 'isPartOf':{'@type':'WebSite','name':'Benjamin Young','url':ORIGIN+'/'}}
    structured = json.dumps(schema or base, ensure_ascii=False).replace('<','\\u003c')
    doc = f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description,quote=True)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#233e32"><meta property="og:type" content="website"><meta property="og:locale" content="en_AU"><meta property="og:site_name" content="Benjamin Young"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{structured}</script><script src="/assets/contact.js" defer></script></head><body>{header()}{content}{footer()}</body></html>'''
    file = DIST / ('index.html' if path == '/' else path.strip('/') + '/index.html')
    file.parent.mkdir(parents=True, exist_ok=True)
    file.write_text(doc)
    if not noindex: PAGES.append(path)

